-- Descriptions of every lakefed_ingest table and column, as Postgres comments. A Lakebase database registered in
-- Unity Catalog shows them as the tables' and columns' comments, so Genie and other AI tools can answer questions
-- about runs, tables and freshness from the schema itself.
-- Applied by the setup job on every run (state_store.apply_comments), apart from the schema migration: comments change
-- no column or row, so they carry no schema version, and a wording change takes effect on the next deploy.
-- Every table and column of lakebase_schema.sql must have one (tests/lakebase_comments_pg_test.py). Statements are
-- split on semicolons with double-hyphen comments removed first, so the text may contain neither.

comment on table lakefed_ingest.control is 'What to ingest: one row per source table (per source database and table). It says where the table is, how to load it (load_type), and which Delta table it lands in (sink_catalog.sink_schema.sink_table). Join checkpoint, ingest_event and control_change on control_id = control.id. A row belongs to one ingestion group (task_collection).';
comment on column lakefed_ingest.control.id is 'Primary key of the table to ingest. Other tables refer to it as control_id.';
comment on column lakefed_ingest.control.job_name is 'Not used by this version (shared with the job orchestration version). Usually null.';
comment on column lakefed_ingest.control.task_collection is 'The ingestion group the table belongs to. One run of the ingestion job ingests one group. An ingestion job in the operations app is a schedule of one or more groups (schedule_member.task_collection).';
comment on column lakefed_ingest.control.src_type is 'Source database engine: sqlserver, oracle, postgresql or mysql.';
comment on column lakefed_ingest.control.src_connection is 'Unity Catalog connection the table is read through when use_remote_query is true. Otherwise, with src_host null, the host and port come from this connection.';
comment on column lakefed_ingest.control.src_host is 'Source server host name for a Spark JDBC read (null when the table is read through a Unity Catalog connection).';
comment on column lakefed_ingest.control.src_port is 'Source server port. Null means the engine default port (1433 SQL Server, 1521 Oracle, 5432 PostgreSQL, 3306 MySQL).';
comment on column lakefed_ingest.control.secret_key is 'Key in the job secret scope that holds this database login as JSON with user and password. Not a secret itself. Null when reading through a Unity Catalog connection.';
comment on column lakefed_ingest.control.src_database is 'Source database name (for Oracle, the service name). With the server it identifies one tenant or client database.';
comment on column lakefed_ingest.control.src_catalog is 'Not used by this version (shared with the job orchestration version). Usually null.';
comment on column lakefed_ingest.control.src_schema is 'Source schema name (for MySQL, the database). Stored names, so Oracle names are usually upper case.';
comment on column lakefed_ingest.control.src_table is 'Source table name.';
comment on column lakefed_ingest.control.sink_catalog is 'Unity Catalog catalog of the target Delta table.';
comment on column lakefed_ingest.control.sink_schema is 'Unity Catalog schema of the target Delta table.';
comment on column lakefed_ingest.control.sink_table is 'Name of the target Delta table. Several rows can share one target table when each has its own client_id.';
comment on column lakefed_ingest.control.client_id is 'Optional tenant id for a shared target table: many source databases write one Delta table, each row of it tagged with this value in the column __client_id__. Null for a target table of its own.';
comment on column lakefed_ingest.control.enable_iceberg_reads is 'Not used by this version (shared with the job orchestration version).';
comment on column lakefed_ingest.control.primary_key is 'Comma-separated key columns of the source table, used to MERGE changes. Required for load types ct and cursor.';
comment on column lakefed_ingest.control.sink_cluster_cols is 'Not used by this version (shared with the job orchestration version).';
comment on column lakefed_ingest.control.load_type is 'How the table is loaded: ct (SQL Server Change Tracking: incremental, deletes included), cursor (incremental by a high-watermark column) or full (the whole table every run). cdc is reserved.';
comment on column lakefed_ingest.control.load_partitioned is 'True to read the first load (seed) or each full load in parallel partitions, for large tables. Needs partition_col and partition_size_mb.';
comment on column lakefed_ingest.control.partition_col is 'Column a partitioned load splits on: numeric, date or datetime, usually an integer key.';
comment on column lakefed_ingest.control.partition_size_mb is 'Target size of each partition of a partitioned load, in MB (for example 2048).';
comment on column lakefed_ingest.control.select_list is 'Comma-separated source columns to copy. Adding a column makes the table load in full once (a reseed).';
comment on column lakefed_ingest.control.use_remote_query is 'True when the table is read through the Unity Catalog connection in src_connection (remote_query), false for a Spark JDBC read with src_host and secret_key.';
comment on column lakefed_ingest.control.ct_enabled is 'Informational for load type ct: whether Change Tracking was seen on the source table. The job checks the source itself.';
comment on column lakefed_ingest.control.cursor_column is 'For load type cursor: the column whose value only grows (a rowversion, an identity or a modified date), read above the last high watermark.';
comment on column lakefed_ingest.control.cdc_capture_instance is 'Reserved for the cdc load type, which is not built yet.';
comment on column lakefed_ingest.control.jdbc_options is 'Optional JSON object of extra Spark JDBC read options, for example fetchsize.';
comment on column lakefed_ingest.control.source_instance_group is 'Optional label for the source server or instance, shown as instance_label in the monitoring rollups. Not used by ingestion.';
comment on column lakefed_ingest.control.tier is 'Optional order within a run: tables run by tier, then priority, then id.';
comment on column lakefed_ingest.control.priority is 'Optional order within a run, after tier.';
comment on column lakefed_ingest.control.warehouse_id is 'Not used by this version, which needs no SQL warehouse for ingestion.';
comment on column lakefed_ingest.control.task_enabled is 'False skips the table in every run without deleting its state. Disabled tables are left out of most counts.';
comment on column lakefed_ingest.control.freshness_sla_minutes is 'Optional freshness target in minutes: an enabled table is late when its last success (checkpoint.last_success_at, or created_at if it never succeeded) is older than this. Null means no target. Monitoring only.';
comment on column lakefed_ingest.control.created_at is 'When the row was added. Rows older than this column show the time the column was added.';
comment on column lakefed_ingest.control.write_mode is 'merge (default): the target table mirrors the source. append (load types ct and full): the target table is a change log with __change_op, __change_version, __extracted_at and __run_id columns.';
comment on column lakefed_ingest.control.client_attrs is 'Optional JSON object of identity columns and values written as text on every row of the target table, for example the tenant name or source server.';

comment on table lakefed_ingest.checkpoint is 'Where each table is: one row per table (control_id), with its load phase, resume position, last outcome and last success. Updated only after a Delta commit, so a failure never skips data. Join control on control_id = control.id.';
comment on column lakefed_ingest.checkpoint.control_id is 'The table this state belongs to (control.id). Primary key.';
comment on column lakefed_ingest.checkpoint.src_database is 'Source database, copied from control for readability.';
comment on column lakefed_ingest.checkpoint.src_schema is 'Source schema, copied from control for readability.';
comment on column lakefed_ingest.checkpoint.src_table is 'Source table, copied from control for readability.';
comment on column lakefed_ingest.checkpoint.strategy is 'Load type that wrote the row: ct, cursor or full. A different control.load_type makes the table load in full again.';
comment on column lakefed_ingest.checkpoint.position is 'Resume position. ct: the source database Change Tracking version. cursor: JSON with the watermark column, its type and value. full: null.';
comment on column lakefed_ingest.checkpoint.phase is 'seeding (needs a full copy, its first load or a reload), incremental (loaded, applying changes, for ct and cursor) or loaded (for full).';
comment on column lakefed_ingest.checkpoint.status is 'Outcome of the last attempt: ok or failed (the error is in detail). A cancelled run never sets failed.';
comment on column lakefed_ingest.checkpoint.detail is 'The last error, or a note, for this table.';
comment on column lakefed_ingest.checkpoint.updated_at is 'When this row last changed.';
comment on column lakefed_ingest.checkpoint.last_success_at is 'When the table last ingested successfully: the basis of freshness and lag. For a ct table whose whole database was found unchanged, also see database_check.checked_at (the later of the two counts).';
comment on column lakefed_ingest.checkpoint.ct_begin_version is 'For ct: the Change Tracking begin version of the table when it was loaded in full. A different value means Change Tracking was turned off and on again, so the table reloads.';
comment on column lakefed_ingest.checkpoint.source_identity is 'The source this checkpoint was written for (engine, host, port, database, schema, table). A control row pointing elsewhere makes the table reload.';
comment on column lakefed_ingest.checkpoint.sink_identity is 'The target table this checkpoint was written for (catalog.schema.table, plus the client_id for a shared table). A control row pointing elsewhere makes the table reload.';
comment on column lakefed_ingest.checkpoint.merge_key is 'The primary key this checkpoint was written for, normalized. A different control.primary_key makes the table reload.';
comment on column lakefed_ingest.checkpoint.key_collation is 'The collation the target table text key columns compare under (for example id=UTF8_LCASE_RTRIM, empty for a table without text keys). Null: not checked yet.';
comment on column lakefed_ingest.checkpoint.select_list is 'The columns the target table was last written with, compared with control.select_list to find added columns.';
comment on column lakefed_ingest.checkpoint.pending_position is 'For append writes: the position an append in progress reaches. Set just before the append and cleared when the checkpoint advances.';
comment on column lakefed_ingest.checkpoint.pending_run_id is 'For append writes: the run (ingest_run.run_id) writing the append in progress. Set means the last run stopped in between, so the next run checks the target first.';

comment on table lakefed_ingest.database_check is 'One check stamp per source database found unchanged as a whole by a run or the check job, instead of a last success on each of its tables. Its checked_at counts as the last success of the database ct tables that are current (position at or past checked_version).';
comment on column lakefed_ingest.database_check.task_collection is 'The ingestion group the database was checked for.';
comment on column lakefed_ingest.database_check.source is 'The database server identity: host or connection, port and login.';
comment on column lakefed_ingest.database_check.src_database is 'The source database.';
comment on column lakefed_ingest.database_check.checked_version is 'The database Change Tracking version when it was found unchanged.';
comment on column lakefed_ingest.database_check.tables is 'How many tables of the database the check covered.';
comment on column lakefed_ingest.database_check.run_id is 'The run that checked it (ingest_run.run_id).';
comment on column lakefed_ingest.database_check.checked_at is 'When the database was found unchanged.';

comment on table lakefed_ingest.check_work is 'The check job work list: the source databases of each ingestion group that have something to ingest, under one work_id. The run started for that work_id ingests only those databases. Rows older than a week are deleted.';
comment on column lakefed_ingest.check_work.work_id is 'The work list id, also on ingest_run.work_id of the run it started.';
comment on column lakefed_ingest.check_work.task_collection is 'The ingestion group.';
comment on column lakefed_ingest.check_work.source is 'The database server identity: host or connection, port and login.';
comment on column lakefed_ingest.check_work.src_database is 'A source database with work.';
comment on column lakefed_ingest.check_work.created_at is 'When the check listed it.';

comment on table lakefed_ingest.reseed_queue is 'Log of every time a table was set to load in full again (a reseed), with why. The reload itself happens because checkpoint.phase is set to seeding.';
comment on column lakefed_ingest.reseed_queue.id is 'Primary key.';
comment on column lakefed_ingest.reseed_queue.control_id is 'The table (control.id).';
comment on column lakefed_ingest.reseed_queue.src_database is 'Source database.';
comment on column lakefed_ingest.reseed_queue.src_schema is 'Source schema.';
comment on column lakefed_ingest.reseed_queue.src_table is 'Source table.';
comment on column lakefed_ingest.reseed_queue.reason is 'Why the table reloads, for example retention_miss (Change Tracking retention ran out), schema_change, ct_disabled, ct_reenabled, ct_version_reset, source_changed, sink_changed, primary_key_changed, sink_missing or key_collation.';
comment on column lakefed_ingest.reseed_queue.enqueued_at is 'When the reload was queued.';
comment on column lakefed_ingest.reseed_queue.processed is 'Reserved, not currently set.';
comment on column lakefed_ingest.reseed_queue.processed_at is 'Reserved, not currently set.';

comment on table lakefed_ingest.ingest_run is 'One row per run of the ingestion job: one ingestion group (task_collection), its timing, status and table counts. Rows with work_id starting check- are the check job own records, not ingestion runs: leave them out when counting or timing runs. Join ingest_event on run_id.';
comment on column lakefed_ingest.ingest_run.run_id is 'Primary key. ingest_event.run_id refers to it.';
comment on column lakefed_ingest.ingest_run.task_collection is 'The ingestion group the run ingested.';
comment on column lakefed_ingest.ingest_run.job_run_id is 'The Databricks job run id, to find the run in the Jobs UI (databricks_run.run_id).';
comment on column lakefed_ingest.ingest_run.cluster_id is 'The Databricks cluster the run used.';
comment on column lakefed_ingest.ingest_run.parallelism is 'The run concurrency budget: how many source queries and writes it ran at once at most.';
comment on column lakefed_ingest.ingest_run.started_at is 'When the run started.';
comment on column lakefed_ingest.ingest_run.finished_at is 'When the run ended. Null while it runs.';
comment on column lakefed_ingest.ingest_run.status is 'running, then completed, failed (a table failed), cancelled (stopped by a cancel, none failed) or skipped (another run of the same group was already running).';
comment on column lakefed_ingest.ingest_run.total is 'Tables in the run (while it runs, the tables it planned).';
comment on column lakefed_ingest.ingest_run.ok is 'Tables that ingested successfully, including unchanged ones.';
comment on column lakefed_ingest.ingest_run.failed is 'Tables that failed.';
comment on column lakefed_ingest.ingest_run.skipped is 'Tables that were unchanged, with nothing to read.';
comment on column lakefed_ingest.ingest_run.reseeded is 'Tables set to load in full again.';
comment on column lakefed_ingest.ingest_run.detail is 'JSON with run details: change detection counts, timings, peak concurrency, rows of batched appends (batch_rows), per-source query shares, table retry totals and cancelled tables.';
comment on column lakefed_ingest.ingest_run.work_id is 'The check job work list the run was started for, as launch id and group. Runs of one launch share the launch id. check- prefix: the check job own record. Null for a run started otherwise.';

comment on table lakefed_ingest.ingest_event is 'One row per table per run (and per retry attempt): what was done, how far it got, rows read and written, timing and any error. Unchanged ct tables get no row (they are counted in ingest_run.skipped). Join ingest_run on run_id and control on control_id.';
comment on column lakefed_ingest.ingest_event.id is 'Primary key.';
comment on column lakefed_ingest.ingest_event.run_id is 'The run (ingest_run.run_id).';
comment on column lakefed_ingest.ingest_event.task_collection is 'The ingestion group of the run.';
comment on column lakefed_ingest.ingest_event.control_id is 'The table (control.id).';
comment on column lakefed_ingest.ingest_event.src_database is 'Source database, copied for convenience.';
comment on column lakefed_ingest.ingest_event.src_schema is 'Source schema, copied for convenience.';
comment on column lakefed_ingest.ingest_event.src_table is 'Source table, copied for convenience.';
comment on column lakefed_ingest.ingest_event.sink_fqn is 'The target Delta table, as catalog.schema.table.';
comment on column lakefed_ingest.ingest_event.action is 'What the run did with the table: seed (first full load), increment (applied changes), reseed (loaded in full again) or full (a full reload).';
comment on column lakefed_ingest.ingest_event.phase is 'The table checkpoint phase when it started: seeding, incremental or loaded.';
comment on column lakefed_ingest.ingest_event.stage is 'How far it got (where it failed, on a failure): plan, detect, verify, ensure_sink, read, seed, merge, load or checkpoint.';
comment on column lakefed_ingest.ingest_event.status is 'running, then ok, failed or cancelled. skipped: a reload was only queued. retried: this attempt failed and a later row has the next attempt.';
comment on column lakefed_ingest.ingest_event.started_at is 'When the table started in this run.';
comment on column lakefed_ingest.ingest_event.finished_at is 'When the table finished in this run.';
comment on column lakefed_ingest.ingest_event.duration_ms is 'How long the table took, in milliseconds.';
comment on column lakefed_ingest.ingest_event.rows_read is 'Rows read from the source, from the Delta commit metrics. Null when not reported.';
comment on column lakefed_ingest.ingest_event.rows_merged is 'Rows written to the target table, from the Delta commit metrics. Null when not reported, and for a batched append (see ingest_run.detail).';
comment on column lakefed_ingest.ingest_event.position_from is 'The checkpoint position before (Change Tracking version or cursor value).';
comment on column lakefed_ingest.ingest_event.position_to is 'The checkpoint position after.';
comment on column lakefed_ingest.ingest_event.pool is 'The Spark scheduler pools the work ran in, or batch followed by its size for a table written in a batched append.';
comment on column lakefed_ingest.ingest_event.error is 'The error of a failed or retried attempt, with its deepest Java cause.';
comment on column lakefed_ingest.ingest_event.retry_count is 'Earlier attempts of this table in the run: 0 for the first attempt, 1 for the first retry.';
comment on column lakefed_ingest.ingest_event.error_kind is 'How a failure was classified for retries: transient, permanent or unknown.';
comment on column lakefed_ingest.ingest_event.error_class is 'A short name for the error: its Spark error class, else its exception type. Groups failures by cause.';

comment on table lakefed_ingest.discovery is 'Table discovery for onboarding: one row per source database read (or per server, for a listing of its databases). Written by the discovery job and the operations app. Not used by ingestion.';
comment on column lakefed_ingest.discovery.discovery_id is 'The discovery id. discovered_table rows of the same discovery share it.';
comment on column lakefed_ingest.discovery.src_type is 'Source database engine: sqlserver, oracle, postgresql or mysql.';
comment on column lakefed_ingest.discovery.src_host is 'Source server host, for a read by host and login (null for a read through a Unity Catalog connection).';
comment on column lakefed_ingest.discovery.src_port is 'Source server port. Null means the engine default port.';
comment on column lakefed_ingest.discovery.src_database is 'The source database read (master on the row that lists a SQL Server databases).';
comment on column lakefed_ingest.discovery.secret_key is 'Key in the secret scope that holds the login. Not a secret itself.';
comment on column lakefed_ingest.discovery.status is 'running, ok, failed, or listed for a discovery that only listed the server databases.';
comment on column lakefed_ingest.discovery.error is 'Why the read failed.';
comment on column lakefed_ingest.discovery.tables is 'How many tables the read found.';
comment on column lakefed_ingest.discovery.requested_by is 'Who asked for the discovery.';
comment on column lakefed_ingest.discovery.started_at is 'When the read started.';
comment on column lakefed_ingest.discovery.finished_at is 'When the read ended.';
comment on column lakefed_ingest.discovery.src_connection is 'Unity Catalog connection the database was read through (null for a read by host and login).';
comment on column lakefed_ingest.discovery.listing is 'JSON describing how the server databases were listed (the name filter and the login template), for a later re-discovery. Never a secret.';

comment on table lakefed_ingest.discovered_table is 'One row per source table a discovery found, with its size and the recommended ingestion settings. Join discovery on discovery_id and src_database. Not used by ingestion until a job is made from it.';
comment on column lakefed_ingest.discovered_table.discovery_id is 'The discovery (discovery.discovery_id).';
comment on column lakefed_ingest.discovered_table.src_database is 'Source database.';
comment on column lakefed_ingest.discovered_table.src_schema is 'Source schema.';
comment on column lakefed_ingest.discovered_table.src_table is 'Source table.';
comment on column lakefed_ingest.discovered_table.row_count is 'Rows in the source table when discovered.';
comment on column lakefed_ingest.discovered_table.size_mb is 'Space the source table takes on the source, in MB (SQL Server allocated size). Tables of 10 GB or more with a partition_candidate load partitioned.';
comment on column lakefed_ingest.discovered_table.ct_enabled is 'Whether Change Tracking is on for the source table.';
comment on column lakefed_ingest.discovered_table.primary_key is 'The source table primary key columns, comma-separated.';
comment on column lakefed_ingest.discovered_table.select_list is 'Recommended columns to copy: every column of a type Spark can read.';
comment on column lakefed_ingest.discovered_table.excluded_columns is 'Columns left out of select_list because Spark cannot read their type.';
comment on column lakefed_ingest.discovered_table.rowversion_column is 'The table rowversion column, if it has one (a good cursor column).';
comment on column lakefed_ingest.discovered_table.identity_column is 'The table identity column, if it has one.';
comment on column lakefed_ingest.discovered_table.load_type is 'Recommended load type: ct (Change Tracking on and a primary key), cursor (a rowversion and a primary key) or full.';
comment on column lakefed_ingest.discovered_table.cursor_column is 'Recommended cursor column, for load type cursor.';
comment on column lakefed_ingest.discovered_table.partition_candidate is 'A column a partitioned load could split on: the first key column if it is an integer or date, else an integer identity column.';
comment on column lakefed_ingest.discovered_table.notes is 'Notes on the recommendation.';
comment on column lakefed_ingest.discovered_table.discovered_at is 'When the table was discovered.';

comment on table lakefed_ingest.control_change is 'Change log of the operations app edits to tables (control) and ingestion jobs (schedules), one row per change, written in the same transaction as the change. Edits made directly with SQL are not logged.';
comment on column lakefed_ingest.control_change.id is 'Primary key.';
comment on column lakefed_ingest.control_change.changed_at is 'When the change was made.';
comment on column lakefed_ingest.control_change.changed_by is 'Who made it: the signed-in user, or re-discovery for tables a daily re-discovery added. Null when unknown.';
comment on column lakefed_ingest.control_change.action is 'What changed: add, register, import, edit, enable, disable, reseed, regroup, or for ingestion jobs schedule_create, schedule_edit, schedule_pause, schedule_resume, schedule_delete or schedule_sync.';
comment on column lakefed_ingest.control_change.control_id is 'The table changed (control.id). Null for an ingestion job change.';
comment on column lakefed_ingest.control_change.task_collection is 'The table ingestion group after the change.';
comment on column lakefed_ingest.control_change.field is 'The column edited. Null for a change to the whole row.';
comment on column lakefed_ingest.control_change.old_value is 'The value before an edit.';
comment on column lakefed_ingest.control_change.new_value is 'The value after an edit.';
comment on column lakefed_ingest.control_change.reseed_reason is 'Set when the change made the table load in full again, with why.';
comment on column lakefed_ingest.control_change.batch_id is 'Groups the rows of one bulk change.';

comment on table lakefed_ingest.schedule is 'An ingestion job of the operations app: a schedule (cadence) of one or more ingestion groups, with its settings. Its groups are in schedule_member. Soft deleted: deleted_at is set and the job is purged after its retention.';
comment on column lakefed_ingest.schedule.id is 'The ingestion job id. schedule_member.schedule_id and app_task.job_id refer to it.';
comment on column lakefed_ingest.schedule.name is 'The ingestion job name, unique among jobs not deleted.';
comment on column lakefed_ingest.schedule.cadence_minutes is 'How often the job runs, in minutes: 5, 10, 15, 20, 30, 60, 120, 180, 240, 360, 720 or 1440 (daily).';
comment on column lakefed_ingest.schedule.timezone is 'The time zone its start times are in.';
comment on column lakefed_ingest.schedule.parameters is 'JSON of ingestion job parameters the job runs with (for example parallelism or table retries).';
comment on column lakefed_ingest.schedule.job_variant is 'Which Databricks job the schedule starts: default (one run per group) or check (the check job first, then runs only for groups with changes).';
comment on column lakefed_ingest.schedule.stagger is 'True to spread the groups start times over the cadence.';
comment on column lakefed_ingest.schedule.paused is 'True when the job is paused: its schedule does not start runs.';
comment on column lakefed_ingest.schedule.notify_emails is 'Comma-separated email addresses told when a run fails.';
comment on column lakefed_ingest.schedule.created_by is 'Who created the job.';
comment on column lakefed_ingest.schedule.created_at is 'When the job was created.';
comment on column lakefed_ingest.schedule.updated_at is 'When the job was last changed.';
comment on column lakefed_ingest.schedule.deleted_at is 'When the job was deleted. Null for a job not deleted. A deleted job is kept for a while so it can be restored, then purged.';
comment on column lakefed_ingest.schedule.options is 'JSON of further settings: start_minute, rediscover_hour (daily re-discovery), the last rediscovery, the job own cluster, removals and the delete state. Null for none.';

comment on table lakefed_ingest.schedule_member is 'The ingestion groups of each ingestion job (schedule): one row per job and group, with the Databricks job the app created to start that group. Soft removed: removed_at is set.';
comment on column lakefed_ingest.schedule_member.id is 'Primary key.';
comment on column lakefed_ingest.schedule_member.schedule_id is 'The ingestion job (schedule.id).';
comment on column lakefed_ingest.schedule_member.task_collection is 'The ingestion group (control.task_collection).';
comment on column lakefed_ingest.schedule_member.offset_minutes is 'When the group starts within the cadence, in minutes after the job start time.';
comment on column lakefed_ingest.schedule_member.job_id is 'The Databricks job the app created to start this group on the schedule.';
comment on column lakefed_ingest.schedule_member.synced_at is 'When that Databricks job was last brought in line with the schedule.';
comment on column lakefed_ingest.schedule_member.sync_error is 'Why the last sync of that Databricks job failed.';
comment on column lakefed_ingest.schedule_member.added_at is 'When the group was added to the job.';
comment on column lakefed_ingest.schedule_member.removed_at is 'When the group was removed from the job. Null while it belongs to it.';

comment on table lakefed_ingest.app_task is 'A large write the operations app runs in the background (creating a job or adding tables or databases of more than 5,000 tables), with its progress and outcome.';
comment on column lakefed_ingest.app_task.id is 'Primary key.';
comment on column lakefed_ingest.app_task.kind is 'What the write is: create (a new ingestion job), tables or databases (added to a job).';
comment on column lakefed_ingest.app_task.request_id is 'The id the page sent with the request, unique, so a request sent again finds the same task.';
comment on column lakefed_ingest.app_task.job_id is 'The ingestion job (schedule.id), once known.';
comment on column lakefed_ingest.app_task.status is 'running, succeeded or failed.';
comment on column lakefed_ingest.app_task.done is 'Tables written so far.';
comment on column lakefed_ingest.app_task.total is 'Tables to write.';
comment on column lakefed_ingest.app_task.result is 'JSON of what the request would have answered, set when the write finished.';
comment on column lakefed_ingest.app_task.error is 'Why the write failed.';
comment on column lakefed_ingest.app_task.created_by is 'Who asked for the write.';
comment on column lakefed_ingest.app_task.created_at is 'When the write started.';
comment on column lakefed_ingest.app_task.heartbeat_at is 'Moved every few seconds while the write runs. A stale heartbeat means the app restarted.';
comment on column lakefed_ingest.app_task.finished_at is 'When the write ended.';
comment on column lakefed_ingest.app_task.progress is 'JSON of a write done one database at a time: its stage, databases done of how many, and tables written.';

comment on table lakefed_ingest.table_upload is 'A CSV file of tables uploaded to the operations app (New ingestion job or Add tables): one row per file. Its lines are in table_upload_line.';
comment on column lakefed_ingest.table_upload.upload_id is 'The upload id.';
comment on column lakefed_ingest.table_upload.file_name is 'The uploaded file name.';
comment on column lakefed_ingest.table_upload.uploaded_by is 'Who uploaded it.';
comment on column lakefed_ingest.table_upload.uploaded_at is 'When it was uploaded.';
comment on column lakefed_ingest.table_upload.columns is 'The file header: its column names.';
comment on column lakefed_ingest.table_upload.lines is 'Lines in the file, header excluded.';
comment on column lakefed_ingest.table_upload.tables is 'Lines that can be taken (status ok).';
comment on column lakefed_ingest.table_upload.invalid is 'Lines that cannot be taken.';

comment on table lakefed_ingest.table_upload_line is 'One row per line of an uploaded CSV of tables (table_upload), keyed by upload_id and line.';
comment on column lakefed_ingest.table_upload_line.upload_id is 'The upload (table_upload.upload_id).';
comment on column lakefed_ingest.table_upload_line.line is 'The line number in the file (the header is line 1).';
comment on column lakefed_ingest.table_upload_line.server is 'The server the line reads: its Unity Catalog connection, or host and port.';
comment on column lakefed_ingest.table_upload_line.src_database is 'Source database.';
comment on column lakefed_ingest.table_upload_line.src_schema is 'Source schema (blank for a line that takes a whole database).';
comment on column lakefed_ingest.table_upload_line.src_table is 'Source table (blank for a line that takes a whole database).';
comment on column lakefed_ingest.table_upload_line.load_type is 'The line own load type, if the file gives one.';
comment on column lakefed_ingest.table_upload_line.fields is 'JSON of the line as read, column to value.';
comment on column lakefed_ingest.table_upload_line.status is 'ok, database (a whole database, found by name when the job is created) or invalid.';
comment on column lakefed_ingest.table_upload_line.errors is 'Why an invalid line cannot be taken.';

comment on table lakefed_ingest.job_selection is 'What an ingestion job was made from: one row per part of the selection (a whole server, a whole database, or named tables), read by re-discovery to know what to add later.';
comment on column lakefed_ingest.job_selection.id is 'Primary key.';
comment on column lakefed_ingest.job_selection.job_id is 'The ingestion job (schedule.id).';
comment on column lakefed_ingest.job_selection.scope is 'server (every database of the server matching filter), database (a whole database) or tables (the tables named).';
comment on column lakefed_ingest.job_selection.server is 'The server: its Unity Catalog connection, or host and port.';
comment on column lakefed_ingest.job_selection.src_database is 'The database, null for a whole server.';
comment on column lakefed_ingest.job_selection.tables is 'The tables named, as schema.table, for scope tables.';
comment on column lakefed_ingest.job_selection.filter is 'The database name filter a whole server was chosen with.';
comment on column lakefed_ingest.job_selection.source_kind is 'Where the selection came from: discovery or upload.';
comment on column lakefed_ingest.job_selection.source_id is 'The discovery or upload id.';
comment on column lakefed_ingest.job_selection.created_by is 'Who made the selection.';
comment on column lakefed_ingest.job_selection.created_at is 'When it was made.';

comment on table lakefed_ingest.databricks_run is 'The Databricks job runs the operations app shows (ingestion group runs, schedule wrappers, check, setup, discovery and delete runs), as its run poller last saw them. ingest_run.job_run_id matches run_id.';
comment on column lakefed_ingest.databricks_run.run_id is 'The Databricks run id. Primary key.';
comment on column lakefed_ingest.databricks_run.job_id is 'The Databricks job the run belongs to.';
comment on column lakefed_ingest.databricks_run.kind is 'What the run is: wrapper (an ingestion job schedule), check, group (an ingestion group run), setup, discover, delete or copies.';
comment on column lakefed_ingest.databricks_run.schedule_id is 'The ingestion job (schedule.id), for wrapper, check and group runs.';
comment on column lakefed_ingest.databricks_run.task_collection is 'The ingestion group a group run ingests.';
comment on column lakefed_ingest.databricks_run.trigger is 'What started the run: PERIODIC (its schedule), RUN_JOB_TASK, ONE_TIME (run now) and others.';
comment on column lakefed_ingest.databricks_run.parameters is 'JSON of the run job parameters.';
comment on column lakefed_ingest.databricks_run.life_cycle_state is 'The Databricks run state: QUEUED, PENDING, RUNNING, TERMINATING, TERMINATED, SKIPPED, INTERNAL_ERROR, or NOT_FOUND when the Jobs API has no such run.';
comment on column lakefed_ingest.databricks_run.result_state is 'How the run ended: SUCCESS, FAILED, CANCELED and others. Null while it runs.';
comment on column lakefed_ingest.databricks_run.state_message is 'The Databricks message about the run state.';
comment on column lakefed_ingest.databricks_run.run_page_url is 'Link to the run page in Databricks.';
comment on column lakefed_ingest.databricks_run.started_at is 'When the run started.';
comment on column lakefed_ingest.databricks_run.ended_at is 'When the run ended.';
comment on column lakefed_ingest.databricks_run.seen_at is 'When the poller last saw the run state change.';
comment on column lakefed_ingest.databricks_run.cancel_requested_at is 'When the app asked Databricks to cancel the run. Null otherwise.';

comment on table lakefed_ingest.rollup_database is 'Monitoring counts per source database (and per group, server and connection), kept current as tables are written: how many tables are loaded, failing or waiting for a first load, and the oldest and newest success. Read instead of counting control and checkpoint.';
comment on column lakefed_ingest.rollup_database.task_collection is 'The ingestion group.';
comment on column lakefed_ingest.rollup_database.src_database is 'The source database (empty when none).';
comment on column lakefed_ingest.rollup_database.server is 'The server key: connection or host and port (empty when none).';
comment on column lakefed_ingest.rollup_database.src_connection is 'The Unity Catalog connection (empty when none).';
comment on column lakefed_ingest.rollup_database.src_host is 'The source host (empty when none).';
comment on column lakefed_ingest.rollup_database.instance_label is 'The control.source_instance_group label (empty when none).';
comment on column lakefed_ingest.rollup_database.tables is 'Enabled tables.';
comment on column lakefed_ingest.rollup_database.no_sla_tables is 'Enabled tables without a freshness target.';
comment on column lakefed_ingest.rollup_database.failing is 'Enabled tables whose last attempt failed.';
comment on column lakefed_ingest.rollup_database.first_load is 'Enabled tables waiting for their first load.';
comment on column lakefed_ingest.rollup_database.loaded is 'Enabled tables neither failing nor waiting for a first load (current or late).';
comment on column lakefed_ingest.rollup_database.control_rows is 'Tables in this grain, enabled or not. 0 once none is left.';
comment on column lakefed_ingest.rollup_database.oldest_success_at is 'The oldest last success among its enabled tables.';
comment on column lakefed_ingest.rollup_database.newest_success_at is 'The newest last success among its enabled tables.';
comment on column lakefed_ingest.rollup_database.newest_any_success_at is 'The newest last success among all its tables, enabled or not.';
comment on column lakefed_ingest.rollup_database.earliest_due_at is 'The earliest time a loaded table with a freshness target goes late. Late now when earlier than the current time.';
comment on column lakefed_ingest.rollup_database.updated_at is 'When these counts were last rewritten.';

comment on table lakefed_ingest.rollup_group is 'Monitoring counts per ingestion group, kept current as tables are written: its tables loaded, failing or waiting for a first load, its databases and servers, and the oldest and newest success.';
comment on column lakefed_ingest.rollup_group.task_collection is 'The ingestion group. Primary key.';
comment on column lakefed_ingest.rollup_group.tables is 'Enabled tables.';
comment on column lakefed_ingest.rollup_group.no_sla_tables is 'Enabled tables without a freshness target.';
comment on column lakefed_ingest.rollup_group.failing is 'Enabled tables whose last attempt failed.';
comment on column lakefed_ingest.rollup_group.first_load is 'Enabled tables waiting for their first load.';
comment on column lakefed_ingest.rollup_group.loaded is 'Enabled tables neither failing nor waiting for a first load.';
comment on column lakefed_ingest.rollup_group.databases is 'Source databases with an enabled table.';
comment on column lakefed_ingest.rollup_group.servers is 'Source servers with an enabled table.';
comment on column lakefed_ingest.rollup_group.oldest_success_at is 'The oldest last success among its enabled tables.';
comment on column lakefed_ingest.rollup_group.newest_success_at is 'The newest last success among its enabled tables.';
comment on column lakefed_ingest.rollup_group.updated_at is 'When these counts were last rewritten.';

comment on table lakefed_ingest.jdbc_connection is 'A JDBC connection made in the operations app: a source server read by host and login, with where the logins are kept. No password is stored here.';
comment on column lakefed_ingest.jdbc_connection.name is 'The connection name. Primary key.';
comment on column lakefed_ingest.jdbc_connection.src_type is 'Source database engine: sqlserver, oracle, postgresql or mysql.';
comment on column lakefed_ingest.jdbc_connection.src_host is 'The source server host.';
comment on column lakefed_ingest.jdbc_connection.src_port is 'The source server port.';
comment on column lakefed_ingest.jdbc_connection.secret_scope is 'The Databricks secret scope that holds its logins.';
comment on column lakefed_ingest.jdbc_connection.secret_key is 'The key of its login in that scope. It may hold {database} for a login per database.';
comment on column lakefed_ingest.jdbc_connection.trust_server_certificate is 'true to accept the server certificate without checking it, false to check it.';
comment on column lakefed_ingest.jdbc_connection.created_by is 'Who made the connection.';
comment on column lakefed_ingest.jdbc_connection.created_at is 'When it was made.';

comment on table lakefed_ingest.jdbc_login_write is 'One row per login the operations app wrote to a secret scope for a JDBC connection: an audit record with no password or secret.';
comment on column lakefed_ingest.jdbc_login_write.id is 'Primary key.';
comment on column lakefed_ingest.jdbc_login_write.connection is 'The JDBC connection (jdbc_connection.name).';
comment on column lakefed_ingest.jdbc_login_write.secret_scope is 'The secret scope the login was written to.';
comment on column lakefed_ingest.jdbc_login_write.secret_key is 'The key it was written under.';
comment on column lakefed_ingest.jdbc_login_write.entered_by is 'Who entered the login.';
comment on column lakefed_ingest.jdbc_login_write.entered_at is 'When it was entered.';
comment on column lakefed_ingest.jdbc_login_write.outcome is 'saved for a new login, rotated when one was already recorded for that scope and key.';

comment on table lakefed_ingest.schema_version is 'The schema versions applied to this database, one row per version, newest highest.';
comment on column lakefed_ingest.schema_version.version is 'The schema version applied.';
comment on column lakefed_ingest.schema_version.applied_at is 'When it was applied.';
comment on column lakefed_ingest.schema_version.applied_by is 'Who or what applied it.';
